INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('f9daabe9-bf48-4537-8e3e-3a4d81346a09', 'rp-01', 'The Busy Executive', '"I''m actually really busy right now."', 'Opening', 'How to handle the time-pressed homeowner and earn 60 seconds of their attention.', 1);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('16079289-cf66-4131-bb32-7ae40249c899', 'rp-02', 'The Instant Brush-Off', '"Not interested."', 'Opening', 'Converting the classic rejection into an opportunity by reframing the conversation.', 2);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('b76c666a-f251-49e8-8180-d6369b73b7cc', 'rp-05', 'The Loyal Customer', '"We already have a lawn company."', 'Turn & Burn', 'Finding the gap in their current service without bashing the competition.', 3);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('c7f30b37-c0bc-460a-8bbd-f4df2461556b', 'rp-07', 'The Denialist', '"My lawn looks fine."', 'Lawn Walk', 'Helping homeowners see what they''re missing with visual evidence.', 4);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('04a99934-0a9d-4d30-a06d-3db7d490a02a', 'rp-11', 'The Budget Objection', '"That''s expensive."', 'Pricing', 'Reframing price as value and investment rather than cost.', 5);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('c60a3a85-31ed-4736-b26d-838fe1a27ecf', 'rp-14', 'The Stall', '"I need to think about it."', 'Closing', 'Isolating the real concern and advancing the decision.', 6);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('ab5b6481-67e1-419f-83fb-ae4da1b04b74', 'rp-ext-01', 'The Skeptical Analyst', '"I need to do my own research first."', 'Full Sale', 'A complete knock-to-prepay-close journey with a research-oriented homeowner who needs proof at every step.', 7);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('73ce747e-636b-4535-8523-e252843104fa', 'rp-ext-02', 'The Reluctant Decision-Maker', '"I need to talk to my husband first."', 'Full Sale', 'Navigating the spouse objection while demonstrating value and urgency to close a prepay sale.', 8);
INSERT INTO comic_stories (id, roleplay_id, title, subtitle, phase, description, order_index) VALUES ('0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 'rp-ext-03', 'The DIY Warrior', '"I can do it myself for way less."', 'Full Sale', 'Converting a proud DIY homeowner by showing the hidden costs and time investment of doing it themselves.', 9);
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('178e45ed-4b60-4f18-80fc-7b2e8c6a5cc7', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157050/arena-ai/playbook/rp-11_panel_1.jpg', 'narrator', 'After the lawn walk, the rep presents the treatment plan.', 'Rep and homeowner at the driveway', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3f3f5f53-79d8-4351-a120-af70514b5b0c', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157091/arena-ai/playbook/rp-11_panel_2.jpg', 'rep', 'For full-year coverage—8 treatments including fertilization, weed control, and grub prevention—it''s $489 for the year.', 'Rep showing tablet with plan', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('cd9eec0a-6aae-4b74-b376-001cd0520589', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157119/arena-ai/playbook/rp-11_panel_3.jpg', 'homeowner', 'Wow. That''s expensive.', 'Homeowner looking taken aback', 'hesitant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('7064f042-0684-4238-90be-f7a57b6efd16', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157153/arena-ai/playbook/rp-11_panel_4.jpg', 'narrator', 'The rep doesn''t discount or get defensive. Instead, they normalize.', 'Close-up of rep staying calm', 'composed');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c6c73edc-60eb-48c1-b620-1ad7db0c609c', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157181/arena-ai/playbook/rp-11_panel_5.jpg', 'rep', 'I understand—lawn care is an investment. Let me break that down for you.', 'Rep using hands to explain', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d0acab72-99c1-4b85-bb2f-c71fad10e6c6', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157211/arena-ai/playbook/rp-11_panel_6.jpg', 'rep', 'That''s about $40 a month. Less than what most people spend on coffee.', 'Rep with relatable comparison', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e9bc77a3-739d-443c-80be-5e8e227d1a36', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157241/arena-ai/playbook/rp-11_panel_7.jpg', 'homeowner', 'I guess when you put it that way...', 'Homeowner''s expression softening', 'considering');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('36f319c2-940e-4161-a7c2-4291572ea6df', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157270/arena-ai/playbook/rp-11_panel_8.jpg', 'rep', 'And think about what you''re getting—a lawn that looks great year-round, no more weekends spreading fertilizer, and we guarantee results.', 'Rep pointing to healthy neighboring lawn', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('b088add1-b5de-488a-ad25-f3368457e69d', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157296/arena-ai/playbook/rp-11_panel_9.jpg', 'homeowner', 'You guarantee it?', 'Homeowner interested in guarantee', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6f441874-8a13-434d-a42b-af1a1f9a9374', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157340/arena-ai/playbook/rp-11_panel_10.jpg', 'rep', '100%. If you''re not satisfied, we re-treat for free. Your lawn will be the best on the block.', 'Rep with confident, reassuring gesture', 'trustworthy');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('94aec886-ebd9-4d1a-b280-d1efb901e328', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157368/arena-ai/playbook/rp-11_panel_11.jpg', 'homeowner', 'Okay, let''s do it.', 'Homeowner smiling, ready to commit', 'convinced');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('38fceb0f-cafc-43f8-99da-210ad5b08487', '04a99934-0a9d-4d30-a06d-3db7d490a02a', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157389/arena-ai/playbook/rp-11_panel_12.jpg', 'narrator', 'By normalizing the price and anchoring to value and guarantees, the rep closed the deal.', 'Handshake or signing moment', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('8ddaea38-8d24-4752-8420-b1f050563e63', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226619/arena-ai/playbook/rp-ext-03_panel_1.jpg', 'narrator', 'A Saturday afternoon. Steve is in his driveway working on his lawn mower when Marcus approaches.', 'Suburban home, homeowner by lawn mower', 'casual');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('42aef563-7fe6-4342-91ef-99819c10c876', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226656/arena-ai/playbook/rp-ext-03_panel_2.jpg', 'rep', 'Hey there! Looks like you''re a hands-on guy. I''m Marcus with GeckoGreen.', 'Rep approaching casually', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9324d5e6-cbb2-4cad-bb10-a51d2f5a462f', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226679/arena-ai/playbook/rp-ext-03_panel_3.jpg', 'homeowner', 'Yeah, I do everything myself. Mowing, edging, all of it. Saves me money.', 'Steve wiping hands, proud', 'proud');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('a9b09bcc-1d9e-4065-8fc5-1b0750d8c0a9', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226718/arena-ai/playbook/rp-ext-03_panel_4.jpg', 'rep', 'I can see that. Your lawn looks better than most on this street. You clearly put in the work.', 'Rep genuinely complimenting', 'appreciative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('7ae12b52-de7f-4521-81e9-a60c6b12f0d5', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226743/arena-ai/playbook/rp-ext-03_panel_5.jpg', 'homeowner', 'Thanks. So what are you selling?', 'Steve direct, no-nonsense', 'direct');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('72bd9c6d-7fd6-4661-a465-b3bad0f4575e', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226770/arena-ai/playbook/rp-ext-03_panel_6.jpg', 'rep', 'Lawn treatment programs. But honestly, looking at your lawn, you''re doing a lot right. Mind if I take a closer look?', 'Rep being genuine', 'honest');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('57a2fb72-7f0b-4784-9ebc-a51dc86b4f6c', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226798/arena-ai/playbook/rp-ext-03_panel_7.jpg', 'homeowner', 'Sure, but I''m not interested in paying someone for something I can do myself.', 'Steve crossing arms', 'resistant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4bbaf9f2-6d91-4caf-b838-24fc8b958c23', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226835/arena-ai/playbook/rp-ext-03_panel_8.jpg', 'narrator', 'They walk across the lawn. Marcus examines areas carefully.', 'Walking onto lawn together', 'observant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6146dd60-396c-43e0-acf6-69f331ac563d', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226853/arena-ai/playbook/rp-ext-03_panel_9.jpg', 'rep', 'You''re mowing at the right height. That''s huge - most people cut too short. But I see some clover and henbit coming in.', 'Pointing to weed patches', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9cd0bc3c-c0a4-4743-97f4-0362633f9a65', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226879/arena-ai/playbook/rp-ext-03_panel_10.jpg', 'homeowner', 'Yeah, I''ve been hitting those with weed killer from the hardware store. Works okay.', 'Steve defensive', 'defensive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('324fc461-1b94-4483-967a-1bfc490d0279', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227039/arena-ai/playbook/rp-ext-03_panel_11.jpg', 'rep', 'It''ll knock them down, but those products don''t have residual control. They come right back.', 'Rep explaining calmly', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('bfab8fed-fe00-44dc-baef-c3236ad125f3', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227068/arena-ai/playbook/rp-ext-03_panel_12.jpg', 'homeowner', 'So I spray again. It''s like $20 a bottle.', 'Steve doing math', 'practical');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('b62e20d1-4931-47aa-a66b-9fea525dd56e', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 13, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227097/arena-ai/playbook/rp-ext-03_panel_13.jpg', 'rep', 'Fair point. Let me ask - how many bottles do you go through a year?', 'Rep genuinely curious', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e0c08e1a-c8c1-4f8f-abf9-db24728c7895', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 14, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227122/arena-ai/playbook/rp-ext-03_panel_14.jpg', 'homeowner', 'I don''t know... maybe 6 or 7? Plus the fertilizer. And I bought grub killer last year.', 'Steve counting on fingers', 'calculating');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('f6f3c5f2-70e9-429e-9a5d-e077b0662a25', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 15, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227145/arena-ai/playbook/rp-ext-03_panel_15.jpg', 'rep', 'So that''s probably $200-250 in products. Plus the spreader, the sprayer... your time.', 'Rep helping with math', 'thoughtful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('08c387db-5e27-460e-a9de-c630a46ffac8', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 16, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227170/arena-ai/playbook/rp-ext-03_panel_16.jpg', 'homeowner', 'My time is free. It''s my day off, might as well be outside.', 'Steve shrugging', 'dismissive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('fc064db6-a1a5-40d8-853a-f550bf1b6c12', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 17, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227228/arena-ai/playbook/rp-ext-03_panel_17.jpg', 'rep', 'I get that. But how many hours you think you spend on treatments, not counting mowing?', 'Rep asking genuinely', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('2470d012-569e-4a4b-8686-68938d83437e', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 18, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227282/arena-ai/playbook/rp-ext-03_panel_18.jpg', 'homeowner', 'I don''t know... couple hours a month during season? Maybe 15-20 hours total.', 'Steve estimating', 'thoughtful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('68a87d31-63b3-4d01-9a63-8c3dbde2fcc9', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 19, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227311/arena-ai/playbook/rp-ext-03_panel_19.jpg', 'rep', 'And if I told you I could get you better results, with products you can''t buy retail, for about the same cost?', 'Rep making value proposition', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('dffba845-aef2-4be9-908b-7373c4525ec5', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 20, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227337/arena-ai/playbook/rp-ext-03_panel_20.jpg', 'homeowner', 'I''d say prove it.', 'Steve skeptical but interested', 'challenging');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('8bcaac5a-233f-486a-ad25-eb11406d31e9', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 21, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227366/arena-ai/playbook/rp-ext-03_panel_21.jpg', 'rep', 'Fair. Our annual program is $499 for your lawn size. That''s 8 professional applications.', 'Rep showing pricing', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('a71901f0-08aa-4736-9463-4a8ea00d38ca', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 22, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227402/arena-ai/playbook/rp-ext-03_panel_22.jpg', 'homeowner', 'That''s more than I spend on products.', 'Steve pushing back', 'resistant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5968c1c7-1427-4743-806b-b91fb4c40684', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 23, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227434/arena-ai/playbook/rp-ext-03_panel_23.jpg', 'rep', 'Maybe by $100-150. But our products are commercial grade - they last longer and work better. And you get those 20 hours back.', 'Rep reframing value', 'persuasive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('ff188d32-e776-4a70-9bd4-bfdf2808ae3b', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 24, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227461/arena-ai/playbook/rp-ext-03_panel_24.jpg', 'homeowner', 'What about the satisfaction of doing it myself?', 'Steve with genuine concern', 'honest');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('23f755af-97c4-4830-832b-9a017fd97529', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 25, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227489/arena-ai/playbook/rp-ext-03_panel_25.jpg', 'rep', 'You still mow, edge, do your landscaping. That''s the visible stuff. We just handle the chemistry that''s honestly harder to get right without training.', 'Rep validating DIY identity', 'understanding');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('12a42134-2ba3-4810-9963-2ca2cb3a00ad', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 26, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227518/arena-ai/playbook/rp-ext-03_panel_26.jpg', 'homeowner', 'The chemistry is where I struggle. I never know the right timing.', 'Steve admitting weakness', 'honest');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('cb74c1e3-4ca7-4255-bf3b-59f7f8f0e2bb', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 27, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227567/arena-ai/playbook/rp-ext-03_panel_27.jpg', 'rep', 'Exactly. That''s what we''re trained for - soil temps, growth cycles, weather timing. You focus on making it look sharp, we handle the science.', 'Rep positioning partnership', 'collaborative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6ae1cb4e-4b83-48b3-9270-d50518dc092e', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 28, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227595/arena-ai/playbook/rp-ext-03_panel_28.jpg', 'homeowner', 'Alright, I''m listening. What''s included?', 'Steve now engaged', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('30dcee42-fdfc-452c-ae0b-316252c0abbe', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 29, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227624/arena-ai/playbook/rp-ext-03_panel_29.jpg', 'rep', '8 treatments: early spring pre-emergent, two fertilizer rounds, weed control through summer, grub prevention, fall winterizer. All guaranteed.', 'Rep listing services', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('a64a4072-6110-47af-bb88-19ac0ece47ab', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 30, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227651/arena-ai/playbook/rp-ext-03_panel_30.jpg', 'homeowner', 'And if I''m not happy?', 'Steve testing', 'cautious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('7d46c4b9-3aca-4e7e-ba95-0193c91eab98', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 31, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227680/arena-ai/playbook/rp-ext-03_panel_31.jpg', 'rep', 'We retreat until you are. No extra charge. If we can''t fix it, you get your money back.', 'Rep stating guarantee', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('f6a94562-6bc1-4211-881b-1366eb41f57b', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 32, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227710/arena-ai/playbook/rp-ext-03_panel_32.jpg', 'homeowner', 'That''s better than the hardware store''s return policy.', 'Steve smirking', 'amused');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('aadf0299-5db7-41cb-9319-6fa0601c8d92', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 33, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227738/arena-ai/playbook/rp-ext-03_panel_33.jpg', 'rep', 'Right? And if you prepay today, I''ll knock off 10%. Makes it $449 for the year.', 'Rep offering discount', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('cd0b0f05-21b3-426e-b50e-1c791bd6ed39', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 34, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227760/arena-ai/playbook/rp-ext-03_panel_34.jpg', 'homeowner', '$449 for the year, and I get my weekends back?', 'Steve considering seriously', 'calculating');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('926c7934-60a9-4e53-bd84-90d76aa6b5df', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 35, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227788/arena-ai/playbook/rp-ext-03_panel_35.jpg', 'rep', 'Your treatment weekends, yeah. You still get to be out here doing the stuff you actually enjoy.', 'Rep reinforcing value', 'encouraging');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('28b72651-5785-422e-88d2-21da33b524fc', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 36, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227836/arena-ai/playbook/rp-ext-03_panel_36.jpg', 'homeowner', 'You know what? Let''s do it. My wife''s been telling me to stop being stubborn.', 'Steve laughing, decided', 'amused');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c0323e7e-c1be-4fce-ac0b-7bd077e91a8d', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 37, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227859/arena-ai/playbook/rp-ext-03_panel_37.jpg', 'rep', 'Smart man. Let me get you set up. Your lawn''s going to look even better, and you''ll wonder why you didn''t do this sooner.', 'Setting up tablet', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('695d976f-cc64-4801-a3ee-c8b91f558e1a', '0f87cde8-f24d-42a3-a3b9-0221fc41ed36', 38, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769227896/arena-ai/playbook/rp-ext-03_panel_38.jpg', 'narrator', 'By validating the DIY identity, showing true costs, and positioning partnership over replacement, Marcus converted the DIY warrior to a prepay customer.', 'Transaction completing, both satisfied', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3df5e729-da3e-418f-8933-927e985bd26e', '16079289-cf66-4131-bb32-7ae40249c899', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155920/arena-ai/playbook/rp-02_panel_1.jpg', 'narrator', 'A neat suburban home. The rep approaches the door with confidence.', 'Walking up to a nice home with visible lawn', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('8b777230-81a7-400c-affd-9dcece4ff11d', '16079289-cf66-4131-bb32-7ae40249c899', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155963/arena-ai/playbook/rp-02_panel_2.jpg', 'rep', 'Good afternoon! I''m with GeckoGreen—', 'Rep at door, smiling', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e99fbde9-ac26-42d0-b9c5-9c6e0d9cf59d', '16079289-cf66-4131-bb32-7ae40249c899', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155989/arena-ai/playbook/rp-02_panel_3.jpg', 'homeowner', 'Not interested.', 'Homeowner at door, arm on doorframe, dismissive posture', 'dismissive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('dc20cda1-ac77-4e65-b272-305ab40bf7ea', '16079289-cf66-4131-bb32-7ae40249c899', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156025/arena-ai/playbook/rp-02_panel_4.jpg', 'narrator', 'Most reps would walk away. But the pro knows this is just a reflex.', 'Close-up of rep maintaining composure', 'determined');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3e0a20c6-cddc-4a3f-8a36-ada3b39b268c', '16079289-cf66-4131-bb32-7ae40249c899', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156073/arena-ai/playbook/rp-02_panel_5.jpg', 'rep', 'I hear that a lot! Before I go—I noticed some grub damage near your walkway. Have you seen it spreading?', 'Rep pointing toward the lawn edge', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5cfd8594-4fc3-477f-a732-ad40905180a5', '16079289-cf66-4131-bb32-7ae40249c899', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156100/arena-ai/playbook/rp-02_panel_6.jpg', 'homeowner', 'Grub damage? What are you talking about?', 'Homeowner''s expression shifts to curiosity', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('ab716d1b-f369-4466-960a-4ec8762617e7', '16079289-cf66-4131-bb32-7ae40249c899', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156141/arena-ai/playbook/rp-02_panel_7.jpg', 'rep', 'See those brown patches right there? That''s grubs eating the roots. Mind if I show you up close?', 'Both looking at brown patch on lawn', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('cd16913c-e6b7-4b5d-9e5f-e0ae789d913f', '16079289-cf66-4131-bb32-7ae40249c899', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156184/arena-ai/playbook/rp-02_panel_8.jpg', 'homeowner', 'I thought that was just dry grass...', 'Homeowner stepping outside, looking concerned', 'surprised');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('0b33a8d1-bca5-473d-a4f5-527c6faa377f', '16079289-cf66-4131-bb32-7ae40249c899', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156068/arena-ai/playbook/rp-02_panel_9.jpg', 'rep', 'Common mistake. The good news is we can fix it before it spreads to the whole lawn.', 'Rep kneeling near damaged grass', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('0306d7ee-3e5e-4b89-bb75-feb20196bbf6', '16079289-cf66-4131-bb32-7ae40249c899', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156229/arena-ai/playbook/rp-02_panel_10.jpg', 'homeowner', 'How much would that cost?', 'Homeowner now fully engaged', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4807d95d-4422-4c68-bf06-2f5b5ccbc818', '16079289-cf66-4131-bb32-7ae40249c899', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156257/arena-ai/playbook/rp-02_panel_11.jpg', 'narrator', 'By reframing to a specific lawn issue, the rep transformed rejection into a genuine opportunity.', 'Wide shot of productive conversation', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('ec88b002-7330-4403-99a2-e6a102bc107f', '73ce747e-636b-4535-8523-e252843104fa', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225566/arena-ai/playbook/rp-ext-02_panel_1.jpg', 'narrator', 'Late afternoon at an upscale suburban home. The lawn has good bones but visible weed problems.', 'Upscale home with manicured landscaping', 'observant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c22bafbc-2532-4fe2-add9-977a99621f75', '73ce747e-636b-4535-8523-e252843104fa', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225609/arena-ai/playbook/rp-ext-02_panel_2.jpg', 'rep', 'Good afternoon! I''m Marcus with GeckoGreen. Beautiful home you have here.', 'At front door, professional and warm', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('26116969-904b-4876-bcbb-03e88c4050b6', '73ce747e-636b-4535-8523-e252843104fa', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225643/arena-ai/playbook/rp-ext-02_panel_3.jpg', 'homeowner', 'Thank you! What can I help you with?', 'Angela at door, polite but busy', 'polite');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3284e82d-a01e-4828-a323-9e6eeb80fc6c', '73ce747e-636b-4535-8523-e252843104fa', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225669/arena-ai/playbook/rp-ext-02_panel_4.jpg', 'rep', 'We''re doing lawn assessments in your neighborhood. I noticed a few things with your lawn - mind if I point them out?', 'Rep gesturing toward lawn', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3cebcadd-5340-44df-be56-96f7652df182', '73ce747e-636b-4535-8523-e252843104fa', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225697/arena-ai/playbook/rp-ext-02_panel_5.jpg', 'homeowner', 'I suppose... but my husband usually handles the lawn decisions.', 'Angela stepping out hesitantly', 'hesitant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6b0cc337-53dd-4cce-87c9-8952a52c34c8', '73ce747e-636b-4535-8523-e252843104fa', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225742/arena-ai/playbook/rp-ext-02_panel_6.jpg', 'rep', 'I understand. I just want to make sure you have the information. Sometimes it helps to know what to discuss with him.', 'Rep being respectful, not pushy', 'understanding');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('20d5039b-dc95-4330-ad16-57fbe319f452', '73ce747e-636b-4535-8523-e252843104fa', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225763/arena-ai/playbook/rp-ext-02_panel_7.jpg', 'narrator', 'They walk onto the lawn together. Marcus points out weed patches.', 'Walking across the front lawn', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('47f6d89c-deb4-4b7c-b656-6ca233872125', '73ce747e-636b-4535-8523-e252843104fa', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225798/arena-ai/playbook/rp-ext-02_panel_8.jpg', 'rep', 'See these spreading here? This is crabgrass - it''ll take over the whole lawn by fall if it''s not treated now.', 'Pointing to crabgrass patches', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('876d7985-6b44-4fce-8360-faa4d365d2a1', '73ce747e-636b-4535-8523-e252843104fa', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225828/arena-ai/playbook/rp-ext-02_panel_9.jpg', 'homeowner', 'Oh wow, I didn''t realize it was spreading that fast.', 'Angela looking concerned at the lawn', 'surprised');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('1baf5b9f-365f-44ff-8b78-8d124d0b7262', '73ce747e-636b-4535-8523-e252843104fa', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225857/arena-ai/playbook/rp-ext-02_panel_10.jpg', 'rep', 'It''s sneaky. And over here - these broadleaf weeds are competing with your grass for nutrients.', 'Moving to another problem area', 'informative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('41d98126-df17-4ca1-b6c9-625d3c6f9216', '73ce747e-636b-4535-8523-e252843104fa', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225885/arena-ai/playbook/rp-ext-02_panel_11.jpg', 'homeowner', 'My husband has been trying to treat these himself, but they keep coming back.', 'Angela frustrated', 'frustrated');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('20a386d5-b5cc-4d55-92ca-749e46bd989b', '73ce747e-636b-4535-8523-e252843104fa', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225910/arena-ai/playbook/rp-ext-02_panel_12.jpg', 'rep', 'That''s common with store-bought products. They kill what''s visible but don''t prevent regrowth. We use commercial-grade products that prevent new weeds.', 'Rep explaining the difference', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('91df0865-e7a5-4f73-aa4a-7af500feac5a', '73ce747e-636b-4535-8523-e252843104fa', 13, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225942/arena-ai/playbook/rp-ext-02_panel_13.jpg', 'homeowner', 'That makes sense. What would a program like that cost?', 'Angela now interested', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4beff977-82bf-4b1a-a4c7-37a07a9edf7c', '73ce747e-636b-4535-8523-e252843104fa', 14, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225967/arena-ai/playbook/rp-ext-02_panel_14.jpg', 'rep', 'For your lawn size, the full annual program is $649. That''s 8 treatments, all weed control, fertilization, and guaranteed results.', 'Rep with tablet showing plan', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('2ef73ce1-b265-46e1-8328-45e48c8bb014', '73ce747e-636b-4535-8523-e252843104fa', 15, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226004/arena-ai/playbook/rp-ext-02_panel_15.jpg', 'homeowner', 'That sounds reasonable, but I really should talk to my husband before committing.', 'Angela hesitating', 'uncertain');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('8b0b4ef1-db6f-480c-9335-b03d28af32b0', '73ce747e-636b-4535-8523-e252843104fa', 16, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226032/arena-ai/playbook/rp-ext-02_panel_16.jpg', 'rep', 'I completely understand. Is there anything specific he''d want to know that I can answer now?', 'Rep being helpful, not pushy', 'supportive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d5ef66d5-465a-4c5f-a721-b78d3aadf92b', '73ce747e-636b-4535-8523-e252843104fa', 17, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226055/arena-ai/playbook/rp-ext-02_panel_17.jpg', 'homeowner', 'He''d probably ask about the guarantee and what happens if we''re not happy.', 'Angela thinking about husband''s concerns', 'thoughtful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('a1538df7-1db2-4398-a4be-88131b2107e6', '73ce747e-636b-4535-8523-e252843104fa', 18, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226082/arena-ai/playbook/rp-ext-02_panel_18.jpg', 'rep', 'Great question. We guarantee results - if your lawn doesn''t improve or weeds return, we retreat at no charge. We don''t stop until you''re satisfied.', 'Rep explaining guarantee confidently', 'trustworthy');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('8bcb549e-0648-4060-b53a-233c8438e637', '73ce747e-636b-4535-8523-e252843104fa', 19, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226109/arena-ai/playbook/rp-ext-02_panel_19.jpg', 'homeowner', 'That''s reassuring. He''d also ask about the timing - when would you start?', 'Angela engaged in conversation', 'engaged');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5ed5dcaf-fdb2-4311-a0ed-3cb69a7fa163', '73ce747e-636b-4535-8523-e252843104fa', 20, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226134/arena-ai/playbook/rp-ext-02_panel_20.jpg', 'rep', 'We could start within the week. Honestly, the crabgrass is in a critical window right now - another few weeks and it seeds. Then you''re fighting it next year too.', 'Rep creating appropriate urgency', 'urgent');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5bedf6f8-769b-4a9e-9962-56b706ae6f51', '73ce747e-636b-4535-8523-e252843104fa', 21, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226163/arena-ai/playbook/rp-ext-02_panel_21.jpg', 'homeowner', 'I didn''t know that. So waiting would make it worse?', 'Angela concerned about timing', 'worried');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('f081b663-37fb-449e-b277-2c2a5ea01052', '73ce747e-636b-4535-8523-e252843104fa', 22, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226197/arena-ai/playbook/rp-ext-02_panel_22.jpg', 'rep', 'Unfortunately yes. Once it seeds, those seeds survive winter. Starting now stops the cycle.', 'Rep nodding seriously', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('fb7d053f-c033-4c7b-97ff-9ad4fdd6393c', '73ce747e-636b-4535-8523-e252843104fa', 23, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226219/arena-ai/playbook/rp-ext-02_panel_23.jpg', 'narrator', 'Angela considers the information. Marcus can see she''s almost ready.', 'Angela thinking, looking at lawn', 'contemplative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('77635033-6b47-4650-9b24-1298aa537bcc', '73ce747e-636b-4535-8523-e252843104fa', 24, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226248/arena-ai/playbook/rp-ext-02_panel_24.jpg', 'rep', 'I''ll tell you what - if you prepay today, I can give you 10% off the annual price. That''s $584 instead of $649.', 'Rep offering incentive', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4af2c690-18eb-4231-b63d-19a75dd69da7', '73ce747e-636b-4535-8523-e252843104fa', 25, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226281/arena-ai/playbook/rp-ext-02_panel_25.jpg', 'homeowner', 'That''s a nice discount... but I still feel like I should check with him.', 'Angela wavering', 'hesitant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('18ac6953-9036-415d-b88c-6b6f484794e2', '73ce747e-636b-4535-8523-e252843104fa', 26, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226309/arena-ai/playbook/rp-ext-02_panel_26.jpg', 'rep', 'How about this - is he reachable by phone? You could give him a quick call and I can answer any questions he has directly.', 'Rep offering solution', 'accommodating');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9b912525-a29d-4657-b405-4463fcd18525', '73ce747e-636b-4535-8523-e252843104fa', 27, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226347/arena-ai/playbook/rp-ext-02_panel_27.jpg', 'homeowner', 'Actually, that''s a good idea. Let me call him.', 'Angela pulling out phone', 'decided');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9b5369f4-6f9c-4242-8d79-7b7505ed8924', '73ce747e-636b-4535-8523-e252843104fa', 28, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226370/arena-ai/playbook/rp-ext-02_panel_28.jpg', 'narrator', 'Angela calls her husband. After a brief conversation, she hands the phone to Marcus.', 'Angela on phone, then passing it', 'transitional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5996a5c3-1609-4d7e-ac19-28419045fd42', '73ce747e-636b-4535-8523-e252843104fa', 29, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226395/arena-ai/playbook/rp-ext-02_panel_29.jpg', 'rep', 'Hi, this is Marcus. Yes sir, I was just showing your wife the crabgrass situation... Right, it''s spreading into the back too...', 'Marcus on phone, professional', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5b6f9a8f-38c7-4fc7-a968-df0ee65d955d', '73ce747e-636b-4535-8523-e252843104fa', 30, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226422/arena-ai/playbook/rp-ext-02_panel_30.jpg', 'narrator', 'After a two-minute conversation, Marcus hands the phone back.', 'Finishing phone call', 'positive');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('f08772d3-c816-4611-b944-71ed99ca3402', '73ce747e-636b-4535-8523-e252843104fa', 31, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226478/arena-ai/playbook/rp-ext-02_panel_31.jpg', 'homeowner', 'He said go ahead and sign us up for the prepay.', 'Angela smiling, relieved', 'happy');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d3857a25-dd8b-4f82-8488-cc2c29ac53fc', '73ce747e-636b-4535-8523-e252843104fa', 32, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226508/arena-ai/playbook/rp-ext-02_panel_32.jpg', 'rep', 'Perfect! Let me get you set up. You made a great decision - your lawn will look incredible.', 'Setting up on tablet', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5a0589a3-6bf7-4c43-a37f-9f0e793ded05', '73ce747e-636b-4535-8523-e252843104fa', 33, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769226533/arena-ai/playbook/rp-ext-02_panel_33.jpg', 'narrator', 'By respecting the spouse concern, providing answers, creating urgency, and facilitating the phone call, Marcus closed the prepay sale.', 'Wide shot of transaction completing', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('13fe71bd-275d-4889-9048-e370894b2e1a', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224638/arena-ai/playbook/rp-ext-01_panel_1.jpg', 'narrator', 'A sunny Saturday morning. Marcus approaches a well-maintained colonial home with a lawn that has some visible issues.', 'Suburban street, walking toward a nice colonial home', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('548e751c-10a2-4f3e-8d24-fe5a7c314c99', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224668/arena-ai/playbook/rp-ext-01_panel_2.jpg', 'rep', 'Good morning! I''m Marcus with GeckoGreen. We''re treating lawns in your neighborhood today.', 'At the front door, professional posture, friendly smile', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e8155f16-f2fd-4993-9a8b-dfe4aa864a2b', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224711/arena-ai/playbook/rp-ext-01_panel_3.jpg', 'homeowner', 'Oh, I''ve seen your trucks around. What exactly do you guys do?', 'Greg at door, curious but guarded expression', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c6ad78ea-74b5-4525-a65b-08644ab262f1', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224731/arena-ai/playbook/rp-ext-01_panel_4.jpg', 'rep', 'We specialize in full-service lawn care - fertilization, weed control, grub prevention. Mind if I take a quick look at your lawn?', 'Rep gesturing toward the lawn', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('87f0f9cb-4ddb-40c0-9f4f-64b06c369667', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224756/arena-ai/playbook/rp-ext-01_panel_5.jpg', 'homeowner', 'Sure, but I should tell you - I research everything before I buy anything.', 'Greg stepping outside, arms crossed', 'skeptical');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('1412c9f5-5256-4810-bafc-79ed7235083f', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224780/arena-ai/playbook/rp-ext-01_panel_6.jpg', 'rep', 'I respect that. Let me show you exactly what I''m seeing so you have real data to work with.', 'Walking toward lawn together', 'understanding');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('10b22588-abb2-42a4-828c-5dc98baabfe8', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224806/arena-ai/playbook/rp-ext-01_panel_7.jpg', 'narrator', 'Marcus begins the lawn walk, pointing out specific issues.', 'Both on the front lawn, examining grass', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('0d9ce06b-40ae-4af1-ae16-056bb4268ce1', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224832/arena-ai/playbook/rp-ext-01_panel_8.jpg', 'rep', 'See this discoloration here? That''s iron chlorosis - your soil pH is off. And these spots? Classic grub damage.', 'Kneeling near brown patches', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4c952667-03c4-4558-b19e-7c58994336f6', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224861/arena-ai/playbook/rp-ext-01_panel_9.jpg', 'homeowner', 'How do you know it''s grubs and not just drought stress?', 'Greg leaning in, interested but testing', 'analytical');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c38619d2-042e-4560-a683-1a72851af100', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224886/arena-ai/playbook/rp-ext-01_panel_10.jpg', 'rep', 'Great question. Watch this.', 'Rep pulling up a section of grass', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('64488287-3a43-4168-978e-5e18ade15c62', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224907/arena-ai/playbook/rp-ext-01_panel_11.jpg', 'narrator', 'Marcus pulls back the turf to reveal the root zone.', 'Close-up of damaged grass roots', 'focused');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4edabf6d-02c9-4013-92d4-5cc034d9347e', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224940/arena-ai/playbook/rp-ext-01_panel_12.jpg', 'rep', 'See how the roots are gone? Drought stress shows in the blades first. Grubs eat from below. Plus, your grass lifts up like carpet.', 'Showing the damaged roots', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('59e41d3f-0da0-409f-979e-e20b7d6a8732', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 13, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769224976/arena-ai/playbook/rp-ext-01_panel_13.jpg', 'homeowner', 'Okay, that''s actually really interesting. What would you do about it?', 'Greg''s expression softening', 'engaged');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('7e9a695f-1044-407d-9259-3e671bb68711', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 14, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225009/arena-ai/playbook/rp-ext-01_panel_14.jpg', 'rep', 'We''d start with a grub treatment now to stop the damage, then reseed these areas. Our 8-application program also corrects the pH over time.', 'Standing, explaining professionally', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('60c138bf-ee20-4685-8e92-f48bb49a19c7', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 15, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225029/arena-ai/playbook/rp-ext-01_panel_15.jpg', 'homeowner', 'How much are we talking?', 'Greg with arms now uncrossed', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('044128c7-d7c6-483c-a81b-6ce74af2eb45', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 16, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225074/arena-ai/playbook/rp-ext-01_panel_16.jpg', 'rep', 'For your property size, the full annual program is $589. That covers everything - 8 treatments, grub prevention, weed control, and guaranteed results.', 'Rep showing tablet with pricing', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('81141950-3f1d-4b37-876e-4e233778bc8d', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 17, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225097/arena-ai/playbook/rp-ext-01_panel_17.jpg', 'homeowner', 'That''s more than I expected. I''d need to compare that to other companies.', 'Greg looking hesitant', 'resistant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c359d9b5-718e-4016-b514-fabac0411dd7', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 18, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225127/arena-ai/playbook/rp-ext-01_panel_18.jpg', 'rep', 'Totally fair. But let me ask - what would you be comparing? Most companies don''t include grub prevention or the soil amendments you need.', 'Rep with open, non-defensive posture', 'understanding');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9c87d413-76b1-402f-83fe-0302ffe2cada', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 19, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225158/arena-ai/playbook/rp-ext-01_panel_19.jpg', 'homeowner', 'I guess I''d need to check what''s included in their programs...', 'Greg considering this point', 'thoughtful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('86e2155e-7ee7-43be-a283-9f7973fe3c01', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 20, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225185/arena-ai/playbook/rp-ext-01_panel_20.jpg', 'rep', 'Here''s what I can tell you - we''re the only company that guarantees results. If you''re not satisfied, we retreat for free. No other company does that.', 'Rep making guarantee gesture', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5f147c81-e0ee-4020-aed7-988521b806e5', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 21, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225208/arena-ai/playbook/rp-ext-01_panel_21.jpg', 'homeowner', 'A guarantee? What exactly does that cover?', 'Greg now more interested', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('5a3704bd-f27f-4de5-b4f8-7802d48c9395', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 22, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225252/arena-ai/playbook/rp-ext-01_panel_22.jpg', 'rep', 'Everything. If weeds come back, we treat again. If you have grub damage, we fix it. If your lawn isn''t greener, we keep working until it is.', 'Rep explaining with conviction', 'trustworthy');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d3ce8be3-60bf-4fcc-b691-bf19f7d15c88', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 23, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225279/arena-ai/playbook/rp-ext-01_panel_23.jpg', 'homeowner', 'Okay, that''s good to know. But $589 all at once is a lot.', 'Greg warming up but still budget conscious', 'hesitant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6ee25fa8-5a43-4cc9-a745-a4e0ac1398f9', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 24, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225301/arena-ai/playbook/rp-ext-01_panel_24.jpg', 'rep', 'I hear you. Here''s the thing - if you prepay today, I can take 10% off. That brings it to $530 for the whole year.', 'Rep offering the discount', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d0b0b8bf-7361-4ff2-9cf1-05d761303c55', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 25, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225323/arena-ai/playbook/rp-ext-01_panel_25.jpg', 'homeowner', '10% off for prepaying?', 'Greg calculating in his head', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('20bf5d5c-780c-4751-813e-77aa8109b5ce', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 26, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225350/arena-ai/playbook/rp-ext-01_panel_26.jpg', 'rep', 'That''s right. And I can split it into two payments if that helps - half today, half in 30 days.', 'Rep accommodating', 'flexible');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('78de005f-6606-49a7-b51c-72979fff620c', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 27, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225386/arena-ai/playbook/rp-ext-01_panel_27.jpg', 'homeowner', 'Two payments would be easier. When would you start?', 'Greg now clearly considering it', 'engaged');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('b2239051-0529-4a5e-820d-a20c5093cf53', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 28, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225418/arena-ai/playbook/rp-ext-01_panel_28.jpg', 'rep', 'We could have our first application done within the next 5-7 business days. You''ll see results within 2 weeks.', 'Rep confident about timeline', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e107ca3b-1a3c-4575-80f7-4787d2fc657c', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 29, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225438/arena-ai/playbook/rp-ext-01_panel_29.jpg', 'homeowner', 'Alright. You''ve given me good information. Let''s do the prepay with two payments.', 'Greg extending hand to shake', 'decided');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d05bcc5f-3f75-4ae1-a0b6-251cb85e4c3b', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 30, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225474/arena-ai/playbook/rp-ext-01_panel_30.jpg', 'rep', 'Excellent choice. Let me get you set up right now. Your lawn is going to look amazing.', 'Shaking hands, both smiling', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('77677a22-89cb-49bb-ac5a-663ef30dc2d5', 'ab5b6481-67e1-419f-83fb-ae4da1b04b74', 31, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769225501/arena-ai/playbook/rp-ext-01_panel_31.jpg', 'narrator', 'By providing proof, addressing objections with data, and offering flexible prepay options, Marcus closed the skeptical analyst.', 'Wide shot of successful transaction on driveway', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('a1559124-0c45-4c36-99f0-55323b615f9c', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156298/arena-ai/playbook/rp-05_panel_1.jpg', 'narrator', 'A well-maintained property. The lawn looks decent but not perfect.', 'Suburban home with okay-looking lawn', 'observant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e945bda2-b5a1-4237-9e18-2c0bdf6acf81', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156328/arena-ai/playbook/rp-05_panel_2.jpg', 'rep', 'Hi! I''m with GeckoGreen. We''re working on a few lawns in the neighborhood today.', 'Rep at door, professional', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c14d9c11-0660-48f6-ac50-795a90742d20', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156355/arena-ai/playbook/rp-05_panel_3.jpg', 'homeowner', 'Oh, we already have a lawn company.', 'Homeowner polite but firm', 'content');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('362a551a-0998-4051-9731-b8250546ea6d', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156389/arena-ai/playbook/rp-05_panel_4.jpg', 'rep', 'That''s great that you have someone! I''m not asking you to switch.', 'Rep with open, non-threatening body language', 'reassuring');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('43c5f496-8e4d-491c-9f18-a153458ea9f8', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156429/arena-ai/playbook/rp-05_panel_5.jpg', 'homeowner', 'So... what are you here for then?', 'Homeowner looking curious', 'intrigued');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3de300ea-8793-4842-bbb6-e994fec7d101', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156453/arena-ai/playbook/rp-05_panel_6.jpg', 'rep', 'I was just noticing a few things they might have missed. Do you mind if I ask—are they treating that crabgrass in the back?', 'Rep gesturing toward backyard', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('56f4c181-9278-4489-b76f-7365c079e5c8', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156485/arena-ai/playbook/rp-05_panel_7.jpg', 'homeowner', 'Crabgrass? I''m not sure... I haven''t really looked back there.', 'Homeowner''s confident expression wavers', 'uncertain');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('08744d79-2b08-4fc4-9ed8-bf7d4e216027', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156512/arena-ai/playbook/rp-05_panel_8.jpg', 'rep', 'Mind if we take a quick look? Sometimes companies miss the edges and back areas.', 'Rep walking alongside homeowner', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9f7d01a9-8ece-4895-8a7c-d70cf173d1f1', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156556/arena-ai/playbook/rp-05_panel_9.jpg', 'homeowner', 'Wow, you''re right. There''s a lot of weeds back here.', 'Looking at weedy backyard area', 'surprised');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d0c13e57-cedf-48f4-8f04-e93dc26b7060', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156591/arena-ai/playbook/rp-05_panel_10.jpg', 'rep', 'We specialize in full-property coverage. I can show you what we include that most companies skip.', 'Rep explaining professionally', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d824ec39-c513-4000-9f2d-e46226b59702', 'b76c666a-f251-49e8-8180-d6369b73b7cc', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156618/arena-ai/playbook/rp-05_panel_11.jpg', 'narrator', 'Without criticizing the competitor, the rep found a service gap and created an opening.', 'Successful conversation continuing', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('e09280ee-7085-4dd6-8041-1e0899b6ec3a', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157451/arena-ai/playbook/rp-14_panel_1.jpg', 'narrator', 'The presentation went well. The homeowner seems interested but hesitates.', 'Rep and homeowner at closing moment', 'tense');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('21350042-17c2-4c77-ad06-02bc61558b5f', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157478/arena-ai/playbook/rp-14_panel_2.jpg', 'homeowner', 'This sounds good, but... I need to think about it.', 'Homeowner with uncertain expression', 'hesitant');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('2eb29ae6-513d-4ec2-9282-4a15aecb9969', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157526/arena-ai/playbook/rp-14_panel_3.jpg', 'narrator', 'The classic stall. Most reps accept it and leave. But not the pro.', 'Close-up of rep''s determined expression', 'focused');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('2f1fce50-b3a3-4b00-a8b1-533c1f26253a', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157554/arena-ai/playbook/rp-14_panel_4.jpg', 'rep', 'Of course! That''s totally fair. Just so I understand—what specifically do you need to think about?', 'Rep with open, curious posture', 'understanding');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('417a2e04-7a25-4f95-8f35-eaa4309999ac', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157581/arena-ai/playbook/rp-14_panel_5.jpg', 'homeowner', 'Well... I should probably talk to my spouse first.', 'Homeowner looking toward the house', 'uncertain');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6e49312f-243f-4a93-924b-95350431c13e', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157610/arena-ai/playbook/rp-14_panel_6.jpg', 'rep', 'That makes total sense. Is it the price you want to discuss with them, or the service itself?', 'Rep isolating the concern', 'analytical');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('68c28f38-ed9b-44ee-ae3c-2b75451acd60', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157641/arena-ai/playbook/rp-14_panel_7.jpg', 'homeowner', 'More the price, I think. We''re trying to watch our spending.', 'Homeowner being honest', 'open');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c426f68f-5217-4b0c-8660-de6ea5c7b48f', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157669/arena-ai/playbook/rp-14_panel_8.jpg', 'rep', 'I get it. What if I told you we have a payment plan that spreads it over 6 months? Would that make the conversation easier?', 'Rep offering solution', 'helpful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('0e969a89-b5bb-4a84-8d5a-ef86117b78b6', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157701/arena-ai/playbook/rp-14_panel_9.jpg', 'homeowner', 'Oh, you can do that? That changes things...', 'Homeowner''s demeanor shifting', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('78685855-7300-470d-a746-5c5c0cab3748', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157749/arena-ai/playbook/rp-14_panel_10.jpg', 'rep', 'Absolutely. And here''s what I can do—let''s get you locked in at today''s rate. If your spouse says no, I''ll cancel it, no questions asked.', 'Rep removing risk', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('b814f601-6fc4-4d58-a08c-4faebdd29c7a', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157777/arena-ai/playbook/rp-14_panel_11.jpg', 'homeowner', 'Alright, let''s do it. I''ll talk to them tonight.', 'Homeowner agreeing', 'decided');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('59643947-bd22-4414-8c79-0dc758eb3a26', 'c60a3a85-31ed-4736-b26d-838fe1a27ecf', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157796/arena-ai/playbook/rp-14_panel_12.jpg', 'narrator', 'By isolating the real concern and removing risk, the rep turned a stall into a close.', 'Successful handshake', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('f674c3e1-ef1b-4c7d-84a9-52e1ee826260', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156647/arena-ai/playbook/rp-07_panel_1.jpg', 'narrator', 'During the lawn walk, the rep and homeowner survey the front yard together.', 'Rep and homeowner on the lawn', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('ef76207e-d35c-4f3d-817b-adca4dcc2a02', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156678/arena-ai/playbook/rp-07_panel_2.jpg', 'homeowner', 'Honestly, my lawn looks fine to me.', 'Homeowner gesturing at lawn with confidence', 'satisfied');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('3238e606-4392-4845-ab4b-2543399ad6dd', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156707/arena-ai/playbook/rp-07_panel_3.jpg', 'rep', 'It does look pretty good from here. I can see you take care of it.', 'Rep nodding in agreement', 'validating');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('563bcbd6-601f-4ad5-946a-73657596c9d9', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156751/arena-ai/playbook/rp-07_panel_4.jpg', 'homeowner', 'See? So I don''t really need your service.', 'Homeowner crossing arms', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('1254ee1c-d835-4de8-83ed-69aaae11df26', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156778/arena-ai/playbook/rp-07_panel_5.jpg', 'rep', 'You''re right, it''s better than most. But see this patch right here?', 'Rep pointing to specific area', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c867bbe7-df39-46c6-b1fc-da50917590b8', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156844/arena-ai/playbook/rp-07_panel_6.jpg', 'narrator', 'The rep kneels down and pulls back some grass to reveal the problem.', 'Close-up of rep examining grass', 'focused');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('c012c98e-5c04-4064-9a50-fe0affe60a3e', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156868/arena-ai/playbook/rp-07_panel_7.jpg', 'rep', 'These are clover weeds. They look like grass from a distance, but they''re actually spreading.', 'Showing clover vs grass difference', 'informative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('bd2f264c-e86f-4736-95be-b1538b61adb6', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156897/arena-ai/playbook/rp-07_panel_8.jpg', 'homeowner', 'I never noticed that before...', 'Homeowner leaning in to look', 'surprised');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9cb59af7-7d6b-42c1-bb36-2a669cf08e54', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156924/arena-ai/playbook/rp-07_panel_9.jpg', 'rep', 'And see how the grass is thin here? That''s a sign of grub activity underneath.', 'Pulling up thin grass to show roots', 'educational');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('822f5e5b-28fd-4829-a0c4-581d40cf9d06', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156960/arena-ai/playbook/rp-07_panel_10.jpg', 'homeowner', 'Can that be fixed?', 'Homeowner now concerned', 'worried');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('b1168d22-f079-4602-8fa5-07d818b76e72', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769156981/arena-ai/playbook/rp-07_panel_11.jpg', 'rep', 'Absolutely. With proper treatment now, we can stop it from spreading and have this looking thick and green by next month.', 'Rep standing confidently', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('38625bc4-9d2d-4e00-abbb-30f4816f02b7', 'c7f30b37-c0bc-460a-8bbd-f4df2461556b', 12, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769157006/arena-ai/playbook/rp-07_panel_12.jpg', 'narrator', 'By validating first, then isolating specific problems with visual proof, the rep created urgency.', 'Productive lawn walk continuing', 'success');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('70bcd006-a4bd-499f-859d-b2522b9cc071', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 1, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155072/arena-ai/playbook/rp-01_panel_1.jpg', 'narrator', 'A sunny afternoon in a nice suburban neighborhood. A GeckoGreen rep walks up a well-maintained driveway.', 'Suburban driveway, nice house, lawn visible', 'confident');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('d9c68061-f6ae-4601-afae-97dabbf2bec3', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 2, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155096/arena-ai/playbook/rp-01_panel_2.jpg', 'rep', 'Hi there! I''m with GeckoGreen—we''re treating lawns in your neighborhood today.', 'At the front door, professional posture', 'friendly');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('ac670daf-81f4-4554-8f6d-0253d56103c8', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 3, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155127/arena-ai/playbook/rp-01_panel_3.jpg', 'homeowner', 'I''m actually really busy right now.', 'Homeowner at door, looking rushed, phone in hand', 'impatient');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('4bbed366-e03e-4969-84da-0e5edf689bd5', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 4, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155150/arena-ai/playbook/rp-01_panel_4.jpg', 'narrator', 'The rep doesn''t push back—instead, they acknowledge the pressure.', 'Close-up of rep''s understanding expression', 'empathetic');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('6d1484fe-912b-4ab7-b007-b74bb7ccf3d1', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 5, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155188/arena-ai/playbook/rp-01_panel_5.jpg', 'rep', 'I totally get it—you''re busy. This will take less than 60 seconds, I promise.', 'Rep holding up hand showing ''one minute'' gesture', 'respectful');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('622dd9dc-6d1d-4e79-ac31-cf8a71ae69f1', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 6, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155224/arena-ai/playbook/rp-01_panel_6.jpg', 'homeowner', 'Okay, 60 seconds...', 'Homeowner''s posture relaxes slightly', 'curious');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('9148470c-dcfc-480a-9eed-b9ebdfc1f6c7', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 7, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155265/arena-ai/playbook/rp-01_panel_7.jpg', 'rep', 'Quick question—who handles your lawn care right now?', 'Rep gesturing toward the lawn', 'professional');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('efa48b91-e605-4a5a-88ea-83db4d705fa3', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 8, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155297/arena-ai/playbook/rp-01_panel_8.jpg', 'homeowner', 'I do it myself, mostly.', 'Homeowner stepping out slightly to look at lawn', 'engaged');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('72bbcbcc-f6a3-44b6-9b30-b6f06ad620c2', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 9, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155325/arena-ai/playbook/rp-01_panel_9.jpg', 'rep', 'I can tell you put effort into it. I noticed a few spots that might need professional treatment—can I show you what I mean?', 'Both looking at the lawn together', 'collaborative');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('2ca35b7f-5b02-45ab-a498-7372dbbea607', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 10, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155354/arena-ai/playbook/rp-01_panel_10.jpg', 'homeowner', 'Sure, show me.', 'Walking toward the lawn', 'interested');
INSERT INTO comic_panels (id, story_id, panel_order, image_url, speaker, dialogue, setting, emotion) VALUES ('19d91b0b-0510-40e9-84a1-da55a526f138', 'f9daabe9-bf48-4537-8e3e-3a4d81346a09', 11, 'https://res.cloudinary.com/dpxfwxxzi/image/upload/v1769155393/arena-ai/playbook/rp-01_panel_11.jpg', 'narrator', 'By respecting their time and asking a qualifying question, the rep earned the right to continue.', 'Wide shot of successful lawn walk beginning', 'success');
